package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;

/** A validated claim form: the amount (negative for a correction), the date ({@code null} when left blank:
 *  the sheet's today), the note, and the number of the claim a correction corrects ({@code null} when left blank). */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects) {

    private static final Pattern SIGNED = Pattern.compile("-?(\\d+(\\.\\d{1,2})?|\\.\\d{1,2})");

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?|\\.\\d{1,2}");

    /** A typed amount (trimmed): required, a number with up to two decimals, 0.00 or more. */
    public static BigDecimal amount(String amount) throws BadRequestException {
        if (amount.isEmpty()) {
            throw new BadRequestException("amount is required");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new BadRequestException("amount must be a number of 0.00 or more with up to two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** A typed claim-form amount (trimmed): required, a number with up to two decimals; a negative one
     *  is a correction. */
    public static BigDecimal signedAmount(String amount) throws BadRequestException {
        if (amount.isEmpty()) {
            throw new BadRequestException("amount is required");
        }
        if (!SIGNED.matcher(amount).matches()) {
            throw new BadRequestException("amount must be a number with up to two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** Whether the amount is a correction's: below zero. */
    public boolean correction() {
        return amount.signum() < 0;
    }

    /** Check the form against the person's claims: a negative amount must name, by number, a SETTLED
     *  claim of the same person; only a negative amount may name one. */
    public void checkCorrection(ClaimRepository repository, String sheetId, long personId) throws BadRequestException {
        if (!correction()) {
            if (corrects != null) {
                throw new BadRequestException("only a negative amount corrects a claim");
            }
            return;
        }
        if (corrects == null) {
            throw new BadRequestException("a negative amount is a correction: name the settled claim it corrects");
        }
        if (!repository.settledOf(sheetId, personId, corrects)) {
            throw new BadRequestException("claim " + corrects + " is not a settled claim of this person");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** Split an amount (more than 0.00, less than the claim's amount) off an OPEN claim not deferred nor in a closed
 *  period, by a user whose role may open a claim: the claim keeps the rest and is unbound from its last statement;
 *  a new OPEN claim with the split-off amount, the same date and note and the next number, opened by the user, with
 *  its due-by fixed now and the original's number as split-from, is listed under the person. Every check is made
 *  before anything is written, so a refusal writes nothing to the store or the audit. Answers the new claim. */
final class ClaimSplit {
    private ClaimSplit() {
    }

    static Claim apply(String id, long cid, String amount, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!found.status().equals("OPEN")) {
            throw new BadRequestException("a " + found.status() + " claim cannot be split");
        }
        if (found.deferred()) {
            throw new BadRequestException("a deferred claim cannot be split");
        }
        BigDecimal part = ClaimInput.amount(amount == null ? "" : amount.trim());
        if (part.signum() <= 0 || part.compareTo(new BigDecimal(found.amount())) >= 0) {
            throw new BadRequestException("the amount split off must be more than 0.00 and less than the claim's amount");
        }
        LocalDate date = LocalDate.parse(found.date());
        PeriodGuard.open(periods, id, date);
        if (!settings.allows(id, "open", by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot open a claim, so cannot split one");
        }
        Rollup.Snapshot before = rollup.take(id);
        Long nid = repository.split(id, found, part, by);
        if (nid == null) {
